<?php
class ModelExtensionProbgServicesCategory extends Model {
    public function addCategory($data){$this->db->query("INSERT INTO ".DB_PREFIX."probg_service_category SET parent_id='".(int)$data['parent_id']."', image='".$this->db->escape($data['image'])."', icon='".$this->db->escape($data['icon'])."', sort_order='".(int)$data['sort_order']."', status='".(int)$data['status']."', date_added=NOW(), date_modified=NOW()");$id=$this->db->getLastId();$this->saveDescriptions($id,$data);$this->saveStores($id,$data);$this->saveLayouts($id,$data);$this->saveSeoUrls($id,$data);$this->cache->delete('probg_services');return $id;}
    public function editCategory($id,$data){$this->db->query("UPDATE ".DB_PREFIX."probg_service_category SET parent_id='".(int)$data['parent_id']."', image='".$this->db->escape($data['image'])."', icon='".$this->db->escape($data['icon'])."', sort_order='".(int)$data['sort_order']."', status='".(int)$data['status']."', date_modified=NOW() WHERE category_id='".(int)$id."'");$this->db->query("DELETE FROM ".DB_PREFIX."probg_service_category_description WHERE category_id='".(int)$id."'");$this->db->query("DELETE FROM ".DB_PREFIX."probg_service_category_to_store WHERE category_id='".(int)$id."'");$this->db->query("DELETE FROM ".DB_PREFIX."probg_service_category_to_layout WHERE category_id='".(int)$id."'");$this->deleteSeoUrls($id);$this->saveDescriptions($id,$data);$this->saveStores($id,$data);$this->saveLayouts($id,$data);$this->saveSeoUrls($id,$data);$this->cache->delete('probg_services');}
    public function deleteCategory($id){$this->db->query("UPDATE ".DB_PREFIX."probg_service_category SET parent_id='0' WHERE parent_id='".(int)$id."'");$this->db->query("DELETE FROM ".DB_PREFIX."probg_service_category WHERE category_id='".(int)$id."'");$this->db->query("DELETE FROM ".DB_PREFIX."probg_service_category_description WHERE category_id='".(int)$id."'");$this->db->query("DELETE FROM ".DB_PREFIX."probg_service_category_to_store WHERE category_id='".(int)$id."'");$this->db->query("DELETE FROM ".DB_PREFIX."probg_service_category_to_layout WHERE category_id='".(int)$id."'");$this->deleteSeoUrls($id);$this->cache->delete('probg_services');}
    public function getCategory($id){return $this->db->query("SELECT c.*,cd.name FROM ".DB_PREFIX."probg_service_category c LEFT JOIN ".DB_PREFIX."probg_service_category_description cd ON(c.category_id=cd.category_id AND cd.language_id='".(int)$this->config->get('config_language_id')."') WHERE c.category_id='".(int)$id."'")->row;}
    public function getCategories($data=array()){$sql="SELECT c.*,cd.name,pcd.name AS parent_name FROM ".DB_PREFIX."probg_service_category c LEFT JOIN ".DB_PREFIX."probg_service_category_description cd ON(c.category_id=cd.category_id AND cd.language_id='".(int)$this->config->get('config_language_id')."') LEFT JOIN ".DB_PREFIX."probg_service_category_description pcd ON(c.parent_id=pcd.category_id AND pcd.language_id='".(int)$this->config->get('config_language_id')."') WHERE 1";if(!empty($data['filter_name']))$sql.=" AND cd.name LIKE '%".$this->db->escape($data['filter_name'])."%'";if(isset($data['filter_status'])&&$data['filter_status']!=='')$sql.=" AND c.status='".(int)$data['filter_status']."'";if(isset($data['filter_parent_id'])&&$data['filter_parent_id']!=='')$sql.=" AND c.parent_id='".(int)$data['filter_parent_id']."'";$sort_data=array('cd.name','pcd.name','c.sort_order','c.status');$sort=isset($data['sort'])&&in_array($data['sort'],$sort_data,true)?$data['sort']:'c.sort_order';$order=isset($data['order'])&&$data['order']==='DESC'?'DESC':'ASC';$sql.=" ORDER BY $sort $order, cd.name ASC";if(isset($data['start'])||isset($data['limit'])){$start=max(0,(int)($data['start']??0));$limit=max(1,(int)($data['limit']??20));$sql.=" LIMIT $start,$limit";}return $this->db->query($sql)->rows;}
    public function getTotalCategories($data=array()){$sql="SELECT COUNT(*) AS total FROM ".DB_PREFIX."probg_service_category c LEFT JOIN ".DB_PREFIX."probg_service_category_description cd ON(c.category_id=cd.category_id AND cd.language_id='".(int)$this->config->get('config_language_id')."') WHERE 1";if(!empty($data['filter_name']))$sql.=" AND cd.name LIKE '%".$this->db->escape($data['filter_name'])."%'";if(isset($data['filter_status'])&&$data['filter_status']!=='')$sql.=" AND c.status='".(int)$data['filter_status']."'";if(isset($data['filter_parent_id'])&&$data['filter_parent_id']!=='')$sql.=" AND c.parent_id='".(int)$data['filter_parent_id']."'";return(int)$this->db->query($sql)->row['total'];}
    public function getCategoryDescriptions($id){$d=array();foreach($this->db->query("SELECT * FROM ".DB_PREFIX."probg_service_category_description WHERE category_id='".(int)$id."'")->rows as $r)$d[$r['language_id']]=$r;return $d;}public function getCategoryStores($id){return array_column($this->db->query("SELECT store_id FROM ".DB_PREFIX."probg_service_category_to_store WHERE category_id='".(int)$id."'")->rows,'store_id');}public function getCategoryLayouts($id){$d=array();foreach($this->db->query("SELECT store_id,layout_id FROM ".DB_PREFIX."probg_service_category_to_layout WHERE category_id='".(int)$id."'")->rows as $r)$d[(int)$r['store_id']]=(int)$r['layout_id'];return $d;}public function getCategoryLayoutId($id,$store_id){$q=$this->db->query("SELECT layout_id FROM ".DB_PREFIX."probg_service_category_to_layout WHERE category_id='".(int)$id."' AND store_id='".(int)$store_id."' LIMIT 1");return $q->num_rows?(int)$q->row['layout_id']:0;}public function getCategorySeoUrls($id){$d=array();foreach($this->db->query("SELECT store_id,language_id,keyword FROM ".DB_PREFIX."seo_url WHERE query='extension/probg_services/category&category_id=".(int)$id."'")->rows as $r)$d[$r['store_id']][$r['language_id']]=$r['keyword'];return $d;}public function getSeoUrlByKeyword($keyword,$store_id,$language_id){return $this->db->query("SELECT seo_url_id,query FROM ".DB_PREFIX."seo_url WHERE keyword='".$this->db->escape($keyword)."' AND store_id='".(int)$store_id."' AND language_id='".(int)$language_id."' LIMIT 1")->row;}
    private function saveDescriptions($id,$data){foreach($data['category_description'] as $language_id=>$v){$meta=trim($v['meta_title'])!==''?$v['meta_title']:$v['name'];$this->db->query("INSERT INTO ".DB_PREFIX."probg_service_category_description SET category_id='".(int)$id."',language_id='".(int)$language_id."',name='".$this->db->escape($v['name'])."',subtitle='".$this->db->escape($v['subtitle'])."',description_short='".$this->db->escape($v['description_short'])."',description='".$this->db->escape($v['description'])."',meta_title='".$this->db->escape($meta)."',meta_description='".$this->db->escape($v['meta_description'])."',meta_keyword='".$this->db->escape($v['meta_keyword'])."'");}}
    private function saveStores($id,$data){foreach(($data['category_store']??array(0)) as $store_id)$this->db->query("INSERT INTO ".DB_PREFIX."probg_service_category_to_store SET category_id='".(int)$id."',store_id='".(int)$store_id."'");}private function saveLayouts($id,$data){if(empty($data['category_layout'])||!is_array($data['category_layout']))return;foreach($data['category_layout'] as $store_id=>$layout_id)if((int)$layout_id>0)$this->db->query("INSERT INTO ".DB_PREFIX."probg_service_category_to_layout SET category_id='".(int)$id."',store_id='".(int)$store_id."',layout_id='".(int)$layout_id."'");}private function saveSeoUrls($id,$data){$stores=$data['category_store']??array(0);foreach($stores as $store_id)foreach($data['category_description'] as $language_id=>$d){$keyword=trim($data['category_seo_url'][$store_id][$language_id]??'');if($keyword==='')$keyword=$this->uniqueSlug($this->slugify($d['name']),$store_id,$language_id,$id);if($keyword!=='')$this->db->query("INSERT INTO ".DB_PREFIX."seo_url SET store_id='".(int)$store_id."',language_id='".(int)$language_id."',query='extension/probg_services/category&category_id=".(int)$id."',keyword='".$this->db->escape($keyword)."'");}}private function deleteSeoUrls($id){$this->db->query("DELETE FROM ".DB_PREFIX."seo_url WHERE query='extension/probg_services/category&category_id=".(int)$id."'");}private function uniqueSlug($slug,$store_id,$language_id,$id){if($slug==='')$slug='service-category';$base=$slug;$i=2;while(true){$r=$this->getSeoUrlByKeyword($slug,$store_id,$language_id);if(!$r||$r['query']==='extension/probg_services/category&category_id='.(int)$id)return $slug;$slug=$base.'-'.$i++;}}private function slugify($v){$m=array('а'=>'a','б'=>'b','в'=>'v','г'=>'g','д'=>'d','е'=>'e','ж'=>'zh','з'=>'z','и'=>'i','й'=>'y','к'=>'k','л'=>'l','м'=>'m','н'=>'n','о'=>'o','п'=>'p','р'=>'r','с'=>'s','т'=>'t','у'=>'u','ф'=>'f','х'=>'h','ц'=>'ts','ч'=>'ch','ш'=>'sh','щ'=>'sht','ъ'=>'a','ь'=>'','ю'=>'yu','я'=>'ya');$v=utf8_strtolower(trim($v));$v=strtr($v,$m);$v=preg_replace('/[^a-z0-9]+/u','-',$v);return trim($v,'-');}
}
